	after->u32[1] = 0;
	after->u32[2] = 0;
	after->u32[3] = 0;

	dmaRef->u32[0] = qwc | 0x30000000;
	dmaRef->u32[1] = (u32)*select;
	dmaRef->u32[2] = 0x11000000;
	dmaRef->u32[3] = qwc | 0x50000000;

	dmaRefVu->u32[0] = (qwc + 2) | 0x30000000;
	dmaRefVu->u32[1] = (u32)header;
